def control(obs):
    phase = obs.get('phase', {})
    direction = phase.get('direction', 'reverse')
    bearing = float(obs.get('route', {}).get('bearing_deg', 0.0))
    hitch = float(obs.get('hitch_deg', 0.0))
    if direction == 'reverse':
        # Build the leftward trailer swing needed for the side road, while
        # backing off as the hitch approaches a moderate angle.
        target = max(18.0, min(32.0, 0.9 * bearing + 10.0))
        steer = max(-25.0, min(25.0, -0.85 * (target - hitch)))
        return (steer, -0.38, 90.0)
    steer = max(-24.0, min(24.0, 0.7 * bearing))
    return (steer, 0.9, 0.0)

