def clamp(x, lo, hi):
    return max(lo, min(hi, x))
def control(obs):
    if obs.get('phase', {}).get('direction') != 'reverse':
        return (0.0, 0.8, 0.0)
    hitch = float(obs.get('hitch_deg', 0.0))
    bearing = float(obs.get('route', {}).get('bearing_deg', 0.0))
    # Recover forward until the hitch is nearly straight.
    if abs(hitch) > 6.0:
        return (clamp(-1.0 * hitch, -22.0, 22.0), 0.55, 0.0)
    # Restart with a very slow reverse and a bounded leftward trailer swing.
    target = clamp(0.35 * bearing + 10.0, 14.0, 20.0)
    steer = clamp(-0.7 * (target - hitch), -18.0, 18.0)
    return (steer, -0.18, 90.0)

