import math

def clamp(x, lo, hi):
    return max(lo, min(hi, x))

def control(obs):
    global recovering
    try:
        phase = obs.get('phase', {})
        direction = phase.get('direction', 'reverse')
        hitch = float(obs.get('hitch_deg', 0.0))
        status = obs.get('status', '')
        if 'recovering' not in globals():
            recovering = (direction == 'reverse' and (status in ('PINNED', 'JACKKNIFED') or abs(hitch) > 32.0))
        if direction == 'reverse':
            if recovering:
                if abs(hitch) < 12.0 and status not in ('PINNED', 'JACKKNIFED'):
                    recovering = False
                else:
                    return (clamp(0.7 * hitch, -18.0, 18.0), 0.55, 0.0)
            desired = 27.0
            steer = clamp(0.9 * (hitch - desired), -24.0, 30.0)
            if abs(hitch) > 38.0:
                steer = clamp(hitch, -24.0, 30.0)
            return (steer, -0.38, 0.0)
        bearing = float(obs.get('route', {}).get('bearing_deg', 0.0))
        steer = clamp(0.65 * bearing - 0.35 * hitch, -25.0, 25.0)
        return (steer, 0.8, 0.0)
    except Exception:
        return (0.0, 0.0, 0.0)

