        speed = -0.10 if gap < 0.8 else -0.16
        return (steer, speed, 0.0)
    bearing = float(obs.get('route', {}).get('bearing_deg', 0.0))
    return (max(-24.0, min(24.0, 0.5 * bearing - 0.3 * hitch)), 0.7, 0.0)

